[{"role": "system", "content": "You are proposing causal mechanics for a governed world model. Return exactly one JSON object and no prose or markdown. You are not writing code. mechanics must hold one mechanic for each of these moves: cut-cedar, saw-slats, mine-graphite, make-leads, make-pencils, supply-materials, buy-stock, pack-box, deliver-boxes, sell-pencil; an empty mechanics list is always rejected. The response must satisfy response_contract. Every effect must be justified by represented state and the action description. Prefer conservative refusal checks over assumptions. Do not add reads/writes fields; the local compiler derives authority. Whenever you name a state path, copy it EXACTLY from allowed_state_paths. Where one change physically sets off another at once (a fall, a break, a spill, a noise heard nearby), write that consequence as a process with timing immediately."}, {"role": "user", "content": "{
  "actions": [
    {
      "description": "Cut cedar and add logs to the loggers' stock.",
      "fields": [],
      "kind": "cut-cedar"
    },
    {
      "description": "Saw logs into cedar slats.",
      "fields": [],
      "kind": "saw-slats"
    },
    {
      "description": "Mine graphite and add it to the miner's stock.",
      "fields": [],
      "kind": "mine-graphite"
    },
    {
      "description": "Mix graphite and clay into pencil leads.",
      "fields": [],
      "kind": "make-leads"
    },
    {
      "description": "Glue leads into slats, paint the pencils, and fit erasers and brass ferrules.",
      "fields": [],
      "kind": "make-pencils"
    },
    {
      "description": "Add paint, erasers, ferrules, and boxes to the supplier's stock.",
      "fields": [],
      "kind": "supply-materials"
    },
    {
      "description": "Buy one unit of a specified stock from a seller.",
      "fields": [
        {
          "name": "seller",
          "type": "entity_ref"
        },
        {
          "name": "stock",
          "type": "string"
        }
      ],
      "kind": "buy-stock"
    },
    {
      "description": "Pack pencils into a box.",
      "fields": [],
      "kind": "pack-box"
    },
    {
      "description": "Start a delivery of packed pencil boxes to a shop.",
      "fields": [
        {
          "name": "shop",
          "type": "entity_ref"
        },
        {
          "name": "quantity",
          "type": "integer"
        }
      ],
      "kind": "deliver-boxes"
    },
    {
      "description": "Sell one pencil to a customer and count the answered shop order.",
      "fields": [
        {
          "name": "customer",
          "type": "entity_ref"
        }
      ],
      "kind": "sell-pencil"
    }
  ],
  "allowed_state_paths": [
    "location.location_id",
